  {mediaMenu&&<div className="song-context-menu media-context-menu" style={{left:mediaMenu.x,top:mediaMenu.y}} onPointerDown={event=>event.stopPropagation()}><strong>{mediaMenu.item.title}</strong><button onClick={()=>{applyBackground(mediaMenu.item);setMediaMenu(null)}}>▧　Set as Preview Background</button><button onClick={()=>{renameMedia(mediaMenu.item);setMediaMenu(null)}}>✎　Rename</button>{mediaMenu.item.mediaType==='Video'&&<button onClick={()=>{setMotionBackground(mediaMenu.item);setMediaMenu(null)}}>↻　{mediaMenu.item.mediaKind==='Motion Background'?'Set as Normal Video':'Set as Motion Background'}</button>}<button onClick={()=>{setMediaProperties(mediaMenu.item);setMediaMenu(null)}}>ⓘ　Properties</button><button onClick={()=>{removeMedia(mediaMenu.item);setMediaMenu(null)}}>×　Remove from Library</button></div>}
  {mediaProperties&&<MediaProperties item={mediaProperties} onClose={()=>setMediaProperties(null)}/>} 
