function VideoControls({playback,control}){const duration=Math.max(0,playback.duration||0),position=Math.min(duration||Infinity,Math.max(0,playback.position||0));return <div className="video-controls"><button onClick={()=>control({playing:!playback.playing})}>{playback.playing?'❚❚ Pause':'▶ Play'}</button><button onClick={()=>control({playing:false,position:0})}>■ Stop</button><button onClick={()=>control({playing:true,position:0})}>↻ Restart</button><span>{formatTime(position)}</span><input className="video-scrubber" type="range" min="0" max={duration||1} step="0.05" value={position} onChange={event=>control({position:Number(event.target.value)})} aria-label="Video position"/><span>{formatTime(duration)}</span><label>Volume<input type="range" min="0" max="1" step="0.05" value={playback.volume} onChange={event=>control({volume:Number(event.target.value)})}/></label><button className={playback.muted?'active':''} onClick={()=>control({muted:!playback.muted})}>{playback.muted?'Unmute':'Mute'}</button><button className={playback.loop?'active':''} onClick={()=>control({loop:!playback.loop})}>Loop</button></div>}
function Sidebar({tab,count,translations=[],translation,setTranslation,recent=[],onRecent,mediaCounts={},mediaFilter,setMediaFilter}){if(tab==='Scriptures')return <aside className="library-sidebar scripture-sidebar"><strong>TRANSLATIONS</strong>{translations.map(item=><button className={item.id===translation?'selected':''} key={item.id} onClick={()=>setTranslation(item.id)}><span className="translation-code">{item.code}</span><small>{item.name}</small></button>)}<strong>RECENT</strong>{recent.length?recent.map(item=><button key={item} onClick={()=>onRecent(item)}>{item}</button>):<p>No references yet</p>}</aside>;if(tab==='Media'){const entries=[['All Media',mediaCounts.all||0],['Videos',mediaCounts.videos||0],['Images',mediaCounts.images||0]];return <aside className="library-sidebar"><strong>MEDIA</strong>{entries.map(([name,total])=><button className={mediaFilter===name?'selected':''} key={name} onClick={()=>setMediaFilter(name)}>{name}<span>{total}</span></button>)}</aside>}const names=tab==='Songs'?['All Songs','Favorites']:tab==='Themes'?['All themes','Songs','Scripture','Presentations']:['All items','Favorites'];return <aside className="library-sidebar"><strong>{tab.toUpperCase()}</strong>{names.map((x,i)=><button className={i===0?'selected':''} key={x}>{x}<span>{i===0?count:''}</span></button>)}</aside>}
function MatchText({text,range}){if(!range)return text;return <>{text.slice(0,range.start)}<mark>{text.slice(range.start,range.end)}</mark>{text.slice(range.end)}</>}
function SongTable({items,selected,inspect,onMenu,onDrag,searching,activeIndex,onActivate}){return <div className={`library-table song-results ${searching?'searching':''}`}><div className="table-head"><span>Title</span><span>{searching?'Author / matching lyric':'Details'}</span><span>{searching?'Match':'Source'}</span></div>{items.map((x,index)=><button key={x.id} draggable onDragStart={event=>onDrag(event,x)} className={`${selected?.id===x.id?'selected':''} ${activeIndex===index&&searching?'keyboard-active':''}`} onMouseEnter={()=>onActivate(index)} onClick={()=>{onActivate(index);inspect(x)}} onContextMenu={event=>onMenu(event,x)}><strong>{x.title}</strong><span className="song-result-detail">{searching&&x.matchText?<small>{x.author}</small>:null}{searching&&x.matchText?<em><MatchText text={x.matchText} range={x.highlight}/></em>:<>{x.detail}</>}</span><span className={x.matchKind==='lyric'?'lyric-match':''}>{searching?x.matchKind==='lyric'?'Lyric match':x.matchKind==='title'?'Title match':'Author match':'Local library'}</span></button>)}{searching&&!items.length&&<div className="no-song-results"><strong>No matching songs</strong><span>Try another title, author, or lyric phrase.</span></div>}</div>}
function BibleBrowser({books,book,setBook,chapter,setChapter,verses,picked,setPicked,reference,setReference,resolveReference,message,inputRef}){const selectedBook=books.find(item=>item.book===book),chapters=Array.from({length:selectedBook?.chapters||0},(_,index)=>index+1),anchor=useRef(null),verseListRef=useRef(null);useEffect(()=>{if(!picked.length)return;verseListRef.current?.querySelector(`[data-verse="${picked[0]}"]`)?.scrollIntoView({block:'nearest'})},[picked]);const selectVerse=(event,number)=>{setPicked(current=>{if(event.shiftKey&&anchor.current!=null){const start=Math.min(anchor.current,number),end=Math.max(anchor.current,number);return verses.filter(item=>item.verse>=start&&item.verse<=end).map(item=>item.verse)}anchor.current=number;if(event.ctrlKey||event.metaKey)return current.includes(number)?current.filter(item=>item!==number):[...current,number].sort((a,b)=>a-b);return[number]})};return <div className="bible-browser"><form className="scripture-reference-bar" onSubmit={event=>{event.preventDefault();resolveReference(reference,{previewResult:true})}}><div><strong>REFERENCE</strong><label>⌕<input ref={inputRef} value={reference} onChange={event=>setReference(event.target.value)} placeholder="Type a reference, e.g. Rom 8:28-31" aria-label="Scripture reference"/></label><small className={message==='Reference not found.'?'error':''}>{message||'Enter loads a reference into Preview · Ctrl+F focuses this field'}</small></div></form><div className="scripture-browser-columns"><div className="book-list">{books.map(item=><button className={item.book===book?'selected':''} key={item.book} onClick={()=>{setBook(item.book);setChapter(1)}}>{item.book}</button>)}</div><div className="chapter-list">{chapters.map(number=><button className={number===chapter?'selected':''} key={number} onClick={()=>setChapter(number)}>{number}</button>)}</div><div className="verse-list" ref={verseListRef}>{verses.map(item=><button data-verse={item.verse} key={item.verse} className={picked.includes(item.verse)?'selected':''} onClick={event=>selectVerse(event,item.verse)}><b>{item.verse}</b><span>{item.text}</span></button>)}</div></div><div className="scripture-actions"><span>{picked.length?`${picked.length} verse${picked.length===1?'':'s'} selected${reference?` · ${reference}`:''}`:`${book} ${chapter} · select verse${verses.length===1?'':'s'} to update Preview`}</span></div></div>}
