function MediaGrid({items,filter,selected,activeIndex,inspect,onActivate,onMenu,onDrag,onMetadata,onImport}){if(!items.length)return <div className="media-empty"><strong>{filter==='All Media'?'No media imported':`No ${filter.toLowerCase()} found`}</strong><span>Import local images or videos, or drop files anywhere in this area.</span><button onClick={onImport}>＋ Import Media</button></div>;return <div className="asset-grid media-grid">{items.map((item,index)=><button key={item.id} draggable onDragStart={event=>onDrag(event,item)} onMouseEnter={()=>onActivate(index)} onClick={()=>{onActivate(index);inspect(item)}} onContextMenu={event=>onMenu(event,item)} className={`${selected?.id===item.id?'selected':''} ${activeIndex===index?'keyboard-active':''} ${item.missing?'missing':''}`}><Thumb item={item} onMetadata={metadata=>onMetadata(item,metadata)}/><strong>{item.missing?'⚠ ':''}{item.title}</strong><small>{item.mediaKind||item.mediaType}{item.duration?` · ${formatTime(item.duration)}`:''}</small></button>)}</div>}
