function ThemeGrid({items,apply,edit,duplicate}){return <div className="theme-grid">{items.map(theme=>{const sample={id:`theme-${theme.id}`,title:theme.name,type:theme.contentType==='Scripture'?'Scripture':'Song',theme,slides:[{name:'Preview',text:theme.contentType==='Scripture'?'In the beginning God created the heavens and the earth.':'Great is Your faithfulness\nGreat is Your faithfulness',reference:theme.contentType==='Scripture'?'Genesis 1:1 (NKJV)':''}]};return <article key={theme.id}><button className="theme-card-preview" onClick={()=>apply(theme)} onDoubleClick={()=>edit(theme)}><Output item={sample}/></button><div><strong>{theme.name}{theme.isDefault?' · Default':''}</strong><small>{theme.contentType} · {theme.layoutType}</small><span><button onClick={()=>edit(theme)}>Edit</button><button onClick={()=>duplicate(theme)}>Duplicate</button></span></div></article>})}</div>}
